// The add-node menu, as the web app's: a cascading tree (category, group, node) with each level in a column beside the row that opened
// it. Up/Down move (and wrap), Right or Enter open a branch or insert, Left or Esc go back a level (Esc at the top closes). The search box has
// the keyboard from the start: type a name and the tree gives way to a flat list of the matches (Enter inserts the chosen one, Esc clears the text).
// Port of webtracker src/graph/menu.js; the grouping table (insert_menu_table.inc) is generated by tools/gen-insert-menu.mjs.
#pragma once

#include <set>
#include <string>
#include <vector>

#include "imgui.h"

namespace wax::app {

struct InsertMenuState {
  std::vector<int> sel{0};   // the row chosen in each column
  int depth = 0;             // the column that has the keys
  bool focus = true;         // the search box takes the keyboard (when opened, and again after Esc clears it)
  bool scrollTo = true;      // bring the chosen row into view (the first frame; the keys set it after that)
  char text[48] = {0};
  int active = 0;            // search: the row chosen
};

// The nodes of the menu by category, in the menu's order: for the tile bank. Only types in `available` are listed.
struct BankGroup { std::string category; std::vector<std::string> types; };
std::vector<BankGroup> menuBank(const std::set<std::string>& available);

// Opens the popup `id` at the mouse and resets the menu.
void openInsertMenu(InsertMenuState& state, const char* id);

// Draws the popup if it is open. `available` is the node types that exist here. Returns the type picked ("" while nothing is).
std::string drawInsertMenu(InsertMenuState& state, const char* id, const std::set<std::string>& available);

}  // namespace wax::app
